from __future__ import annotations

import contextlib
import json
from pathlib import Path

from numbertrace.models import Investigation


def render_json(inv: Investigation) -> str:
    payload = inv.model_dump(mode="json")
    payload["_report_notice"] = (
        "Local report generated by NumberTrace OSINT. Web findings are unverified public "
        "references. Treat with care: it contains the investigated number."
    )
    return json.dumps(payload, indent=2, ensure_ascii=False)


def write_reports(inv: Investigation, html_path: Path | None, json_path: Path | None) -> list[Path]:
    from numbertrace.reporting.html_report import render_html

    written: list[Path] = []
    for path, content in (
        (html_path, render_html(inv) if html_path else ""),
        (json_path, render_json(inv) if json_path else ""),
    ):
        if path is None:
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        with contextlib.suppress(OSError):
            path.chmod(0o600)
        written.append(path)
    return written
